variable.schema:
Property = {
  str: number  // 力量
  dex: number  // 敏捷
  con: number  // 体质
  int: number  // 智力
  wis: number  // 感知
  cha: number  // 魅力
}
// 60 is the human average

{
  name: string
  desc: string
  property: Property
}

{
  "$id": {
    name: string
    desc: string
    relation: '友好' | '中立' | '敌对' | string  // 2-4字符
    status: '健康' | '危险' | '死亡' | string    // 2-4字符
    statusDesc: string
    property: Property
  }
}

{
  "$id": {
    name: string
    type: string    // 四字以内
    level: number
    status: string
    desc: string    // 以功能为主
  }
}

{
  "$id": {
    name: string
    type: string    // 2-4字符
    status: string  // 剩余数量, 2-6字符
    desc: string
  }
}
